CREATE TABLE IF NOT EXISTS npc_spawn_makers (
    name                TEXT    PRIMARY KEY
  , area_span           TEXT    NOT NULL
  , area_exclusions     TEXT
  , max_npc_count       INTEGER NOT NULL     CHECK(max_npc_count >= 0)
  , spawn_conditions    TEXT
  , custom_behavior     TEXT
  , behavior_parameters TEXT
);

-- noinspection SqlWithoutWhere
DELETE FROM npc_spawn_makers;































